(function () {
    function toRad(value) {
        return value * Math.PI / 180;
    }
    function distanceKm(lat1, lon1, lat2, lon2) {
        var earth = 6371;
        var dLat = toRad(lat2 - lat1);
        var dLon = toRad(lon2 - lon1);
        var a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
            Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) *
            Math.sin(dLon / 2) * Math.sin(dLon / 2);
        return earth * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    }

    var button = document.getElementById('locate-nearest-branch');
    var result = document.getElementById('branch-location-result');
    var list = document.getElementById('branch-list');

    button.addEventListener('click', function () {
        if (!navigator.geolocation) {
            result.textContent = 'المتصفح لا يدعم تحديد الموقع.';
            return;
        }
        result.textContent = 'جاري تحديد موقعك';
        navigator.geolocation.getCurrentPosition(function (position) {
            var lat = position.coords.latitude;
            var lon = position.coords.longitude;
            var cards = Array.from(list.querySelectorAll('.qt-branch-card'));

            cards.forEach(function (card) {
                var branchLat = parseFloat(card.dataset.latitude || '0');
                var branchLon = parseFloat(card.dataset.longitude || '0');
                var distance = branchLat && branchLon
                    ? distanceKm(lat, lon, branchLat, branchLon)
                    : Number.POSITIVE_INFINITY;
                card.dataset.distance = String(distance);
                var distanceLabel = card.querySelector('.qt-branch-distance');
                distanceLabel.textContent = Number.isFinite(distance)
                    ? distance.toFixed(1) + ' كم تقريبًا'
                    : 'موقع الفرع غير محدد';
            });

            cards.sort(function (a, b) {
                var aOpen = a.dataset.open === '1' ? 0 : 1;
                var bOpen = b.dataset.open === '1' ? 0 : 1;
                if (aOpen !== bOpen) return aOpen - bOpen;
                return parseFloat(a.dataset.distance || '999999') -
                       parseFloat(b.dataset.distance || '999999');
            });
            cards.forEach(function (card) { list.appendChild(card); });
            if (cards.length) cards[0].classList.add('qt-nearest-branch');
            result.textContent = 'تم ترتيب الفروع من الأقرب إلى الأبعد.';
        }, function () {
            result.textContent = 'تعذر تحديد الموقع. يمكنك اختيار الفرع يدويًا.';
        }, {
            enableHighAccuracy: true,
            timeout: 10000,
            maximumAge: 60000
        });
    });
})();
